content.content:
public class Program {
    public static void main(String[] args) {
        int age = 30;
        if (age < 16) {
            // 如果 age 小于 16 则输出 Too Young
            System.out.println("Too Young");
        } else {
            // 否则输出 Welcome!
            System.out.println("Welcome!");
        }
    }
}

